<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/classes/GreenPortalDatabase.php';
function arg(string $name,string $default=''):string{foreach($GLOBALS['argv'] as $v)if(str_starts_with($v,'--'.$name.'='))return substr($v,strlen($name)+3);return $default;}
function tableExists(PDO $p,string $db,string $table):bool{$q=$p->prepare("SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=? AND TABLE_NAME=? AND TABLE_TYPE='BASE TABLE'");$q->execute([$db,$table]);return(bool)$q->fetchColumn();}
$env=GreenPortalDatabase::env();$origins=array_values(array_filter(array_map('trim',explode(',',arg('origins')))));$target=arg('target');$ged=arg('ged');if(!$origins||!$target||!$ged)throw new RuntimeException('Use --origins=banco1,banco2 --target=gempresa_dbp --ged=E:\\projetoGreen\\GED\\green_empresa');if(!preg_match('/^g[a-z0-9]+_dbp$/i',$target))throw new RuntimeException('Banco destino invalido.');if(!is_dir($ged))throw new RuntimeException('Caminho GED nao encontrado: '.$ged);
$server=new PDO('mysql:host='.($env['GPT_DB_HOST']??'127.0.0.1').';port='.($env['GPT_DB_PORT']??'3306').';charset=utf8mb4',(string)($env['GPT_DB_USERNAME']??''),(string)($env['GPT_DB_PASSWORD']??''),[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);$result=['modo'=>'DRY_RUN','alterou_banco'=>false,'criou_banco'=>false,'destino'=>$target,'ged'=>$ged,'origens'=>[],'tabelas'=>[],'avisos'=>[],'gerado_em'=>date('c')];
foreach($origins as $origin){if(!preg_match('/^[A-Za-z0-9_]+$/',$origin))throw new RuntimeException('Banco origem invalido: '.$origin);$q=$server->prepare('SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=?');$q->execute([$origin]);if(!(int)$q->fetchColumn())throw new RuntimeException('Banco origem nao encontrado: '.$origin);$p=GreenPortalDatabase::connect($env,$origin,'LEGADO_MODELO');$result['origens'][$origin]=[];foreach(['legislacaoxempresa','li_licencas','legislacaoxlicencas','infraestrutura','infraestruturaxunidades','laia','lais','lpro','mm_monitoramento'] as $table){if(!tableExists($p,$origin,$table))continue;$result['tabelas'][$table]=($result['tabelas'][$table]??0)+(int)$p->query('SELECT COUNT(*) FROM `'.$table.'`')->fetchColumn();}}
$q=$server->prepare('SELECT COUNT(*) FROM information_schema.SCHEMATA WHERE SCHEMA_NAME=?');$q->execute([$target]);if((int)$q->fetchColumn())$result['avisos'][]='O banco destino ja existe; a simulacao nao fara backup nem carga.';else$result['avisos'][]='O banco destino seria provisionado a partir de gmodelo_dbp.';$file=dirname(__DIR__).'/storage/logs/migracao/dry_run_'.preg_replace('/[^A-Za-z0-9_]/','_',$target).'_'.date('Ymd_His').'.json';@mkdir(dirname($file),0770,true);file_put_contents($file,json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT));$result['relatorio']=$file;echo json_encode($result,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_PRETTY_PRINT),PHP_EOL;
